let context;
export function playEffect(success){try{if(localStorage.getItem('giolingo.effects')==='off')return;const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;context ||= new Audio();context.resume().catch(()=>{});const start=context.currentTime;for(const [i,frequency]of (success?[523.25,659.25,783.99]:[280,220]).entries()){const oscillator=context.createOscillator(),gain=context.createGain();oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.setValueAtTime(0,start+i*.085);gain.gain.linearRampToValueAtTime(.07,start+i*.085+.015);gain.gain.exponentialRampToValueAtTime(.001,start+i*.085+.2);oscillator.connect(gain);gain.connect(context.destination);oscillator.start(start+i*.085);oscillator.stop(start+i*.085+.22);}}catch{/* Playback restrictions must never block an answer. */}}
